$:set -euo pipefail
git fetch origin main
git checkout --detach origin/main
python3 - <<'PY'
from pathlib import Path
p=Path("workspaces/extractor-srs-design/runtime/octane-response-parser.js")
src=p.read_text()
needle='    if(!text.trim())fail(ErrorType,"OCTANE_EMPTY_MESSAGE","Unrecoverable message at index "+index);\n'
assert src.count(needle)==1, "Expected one Octane empty-content guard"
src=src.replace(needle,"")
version='decoder:{name:"octane-visible",version:"1.0.0"}'
assert src.count(version)==1, "Expected one Octane version"
src=src.replace(version,'decoder:{name:"octane-visible",version:"1.0.1"}')
p.write_text(src)
t=Path("workspaces/extractor-srs-design/tests/octane-response-parser.test.js")
source=t.read_text()
old='''test("Octane rejects absent assistant, duplicate IDs and unrecoverable display content",()=>{
 const u=[{id:"u",role:"user",content:"Hi"}];
 assert.throws(()=>parseHtmlResponse(html(u),validated),e=>e.code==="INCOMPLETE_OCTANE");
 assert.throws(()=>parseHtmlResponse(html([{id:"a",role:"user",content:"x"},{id:"a",role:"assistant",content:"y"}]),validated),e=>e.code==="INVALID_OCTANE_MESSAGE");
 assert.throws(()=>parseHtmlResponse(html([{id:"a",role:"user",content:"x"},{id:"b",role:"assistant",content:""}]),validated),e=>e.code==="OCTANE_EMPTY_MESSAGE");
});'''
new='''test("Octane rejects absent assistant, duplicate IDs and non-string content",()=>{
 const u=[{id:"u",role:"user",content:"Hi"}];
 assert.throws(()=>parseHtmlResponse(html(u),validated),e=>e.code==="INCOMPLETE_OCTANE");
 assert.throws(()=>parseHtmlResponse(html([{id:"a",role:"user",content:"x"},{id:"a",role:"assistant",content:"y"}]),validated),e=>e.code==="INVALID_OCTANE_MESSAGE");
 for(const bad of [null,0,{},[]]){
   assert.throws(()=>parseHtmlResponse(html([{id:"u",role:"user",content:"Hi"},{id:"a",role:"assistant",content:bad}]),validated),e=>e.code==="INVALID_OCTANE_CONTENT");
 }
});
test("Octane preserves empty and whitespace-only content without inventing text",()=>{
 const source=[
  {id:"u1",role:"user",content:"Hi"},
  {id:"a1",role:"assistant",content:"",reasoningSummary:"Worked for 6m 10s",hideActions:true,renderedHtml:""},
  {id:"a2",role:"assistant",content:"   ",reasoningSummary:"Processing",renderedHtml:""},
  {id:"u2",role:"user",content:""},
  {id:"a3",role:"assistant",content:"",renderedHtml:""}
 ];
 const parsed=parseHtmlResponse(html(source),validated);
 assert.deepEqual(parsed.selected.counts,{user:2,commentary:0,final:3});
 assert.deepEqual(parsed.selected.messages.map(m=>m.text),["Hi","","   ","",""]);
 assert.deepEqual(parsed.selected.messages.map(m=>m.text_origin),["content","content","content","content","content"]);
 assert.deepEqual(parsed.linear.records.map(r=>r.derived_text),["Hi","","   ","",""]);
 assert.deepEqual(parsed.linear.records[1].raw_node,source[1]);
 assert.deepEqual(parsed.linear.records[2].raw_node,source[2]);
 assert.equal(parsed.linear.source_node_count,5);
});'''
assert source.count(old)==1, "Expected one original Octane rejection test"
t.write_text(source.replace(old,new))
PY
echo '=== VALIDATION ==='
node --test workspaces/extractor-srs-design/tests/*.test.js workspaces/extractor-srs-design/input-validator.test.js
echo '=== DIFF CHECK ==='
git diff --check
git diff --stat
git diff -- workspaces/extractor-srs-design/runtime/octane-response-parser.js workspaces/extractor-srs-design/tests/octane-response-parser.test.js
echo '=== COMMIT ==='
git config user.name "github-actions[bot]"
git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
git add -- workspaces/extractor-srs-design/runtime/octane-response-parser.js workspaces/extractor-srs-design/tests/octane-response-parser.test.js
git commit -m "Allow empty Octane message content and cover metadata-only records"
gh auth setup-git
for attempt in 1 2 3; do
  if git push origin HEAD:main; then echo "PUBLISHED_COMMIT $(git rev-parse HEAD)"; exit 0; fi
  git fetch origin main
  git rebase origin/main
done
echo 'PUSH_FAILED' >&2
exit 1
